// Valida y normaliza el lead que llega desde el sitio (formulario o chatbot)
const b = $json.body || {};
const clean = (v, max = 500) => String(v ?? '').trim().slice(0, max);
const digits = (v) => String(v ?? '').replace(/\D/g, '');
const html = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');

const lead = {
  origen: clean(b.origen, 30) || 'formulario',
  formulario: clean(b.formulario, 30),
  nombre: clean(b.nombre, 80),
  telefono: digits(b.telefono).slice(-11),
  email: clean(b.email, 120).toLowerCase(),
  interes: clean(b.interes, 40),
  licencia: clean(b.licencia, 20),
  mensaje: clean(b.mensaje, 1500),
  consentimiento: b.consentimiento === true,
  consentimiento_texto: clean(b.consentimiento_texto, 1000),
  idioma: clean(b.idioma, 5),
  pagina: clean(b.pagina, 300),
  fecha: clean(b.fecha, 40) || new Date().toISOString(),
  utm_source: clean(b.utm?.utm_source, 100),
  utm_medium: clean(b.utm?.utm_medium, 100),
  utm_campaign: clean(b.utm?.utm_campaign, 100),
  utm_term: clean(b.utm?.utm_term, 100),
  utm_content: clean(b.utm?.utm_content, 100),
  referrer: clean(b.utm?.referrer, 300),
  ip: clean($json.headers?.['x-forwarded-for'], 60),
  user_agent: clean($json.headers?.['user-agent'], 300),
};

const telOk = lead.telefono.length === 10 || (lead.telefono.length === 11 && lead.telefono.startsWith('1'));
const emailOk = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(lead.email);
lead.valido = !b.empresa && lead.nombre.length >= 2 && telOk && emailOk && lead.consentimiento;

const etiquetas = { salud: 'Seguro de salud', vida: 'Seguro de vida', medicare: 'Medicare', dental: 'Dental y visión', otro: 'Otra consulta', equipo: 'Unirse al equipo' };
lead.interes_texto = etiquetas[lead.interes] || lead.interes || '—';
lead.telefono_formato = lead.telefono.length >= 10
  ? `(${lead.telefono.slice(-10, -7)}) ${lead.telefono.slice(-7, -4)}-${lead.telefono.slice(-4)}`
  : lead.telefono;

lead.nombre_html = html(lead.nombre);
lead.interes_texto_html = html(lead.interes_texto);
lead.origen_html = html(lead.origen);
lead.formulario_html = html(lead.formulario);
lead.email_html = html(lead.email);
lead.licencia_html = html(lead.licencia);
lead.mensaje_html = html(lead.mensaje);
lead.idioma_html = html(lead.idioma);
lead.pagina_html = html(lead.pagina);
lead.fecha_html = html(lead.fecha);
lead.consentimiento_texto_html = html(lead.consentimiento_texto);
lead.utm_source_html = html(lead.utm_source);
lead.utm_medium_html = html(lead.utm_medium);
lead.utm_campaign_html = html(lead.utm_campaign);
lead.email_attr = html(lead.email);
lead.nombre_subject = lead.nombre.replace(/[\r\n]+/g, ' ');
lead.interes_subject = lead.interes_texto.replace(/[\r\n]+/g, ' ');

return [{ json: lead }];
